"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["82559"],{49316(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>h,assets:()=>l});var a=JSON.parse('{"id":"tangfen/aqspirit","title":"","description":"The habitual trick of all anti-Marx people is to falsify and distort, then wave their fists at the concepts they themselves fabricated, and then declare Marx defeated. This method, which fully reveals their true colors, is also commonly seen on forums. Yesterday, [Dushulang], Yixuan, and Banong Guocui -- three accounts -- posted three different threads, all with identical content demonstrating this very point. Whether these three accounts belong to the same person or the same group is unimportant.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/aqspirit.md","sourceDirName":"tangfen","slug":"/tangfen/aqspirit","permalink":"/en/tangfen/aqspirit","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"aqspirit","title":"","hide_table_of_contents":true,"sidebar_label":"The Ah Q spirit of anti-Marxists like Dushulang, Yixuan, Banong Guocui!"},"sidebar":"tangfenSidebar","previous":{"title":"Qingyushan2, discussing Marxist theory naturally includes anti-Marxist views!","permalink":"/en/tangfen/qys"},"next":{"title":"Dushulang and others, please know your place!","permalink":"/en/tangfen/readingwolf"}}'),i=n(74848),o=n(28453);let s={id:"aqspirit",title:"",hide_table_of_contents:!0,sidebar_label:"The Ah Q spirit of anti-Marxists like Dushulang, Yixuan, Banong Guocui!"},r="The Ah Q Spirit of Dushulang, Yixuan, Banong Guocui and Other Anti-Marx Folks!",l={},h=[];function c(e){let t={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"the-ah-q-spirit-of-dushulang-yixuan-banong-guocui-and-other-anti-marx-folks",children:"The Ah Q Spirit of Dushulang, Yixuan, Banong Guocui and Other Anti-Marx Folks!"})}),"\n",(0,i.jsx)(t.p,{children:"The habitual trick of all anti-Marx people is to falsify and distort, then wave their fists at the concepts they themselves fabricated, and then declare Marx defeated. This method, which fully reveals their true colors, is also commonly seen on forums. Yesterday, [Dushulang], Yixuan, and Banong Guocui -- three accounts -- posted three different threads, all with identical content demonstrating this very point. Whether these three accounts belong to the same person or the same group is unimportant."}),"\n",(0,i.jsx)(t.p,{children:"The story they jointly fabricated is that they defeated Tangfen. This probably did happen -- just as Ah Q routinely accomplished things. In Ah Q's mind, what couldn't be accomplished? Unfortunately, the fact is: my posts are all titled starting with \"For all who distort Marx.\" If the Ah Qs consider themselves representatives of \"all who distort Marx\" and defeated Tangfen in their dreams, I don't mind certain people's fondness for self-gratification -- please continue."}),"\n",(0,i.jsx)(t.p,{children:"But the difference between Marx and anti-Marx people is absolutely not something Ah Q's dreams can cover up. Marx stands solely on the basis of realistic logical relationships, while anti-Marx people only play tricks going from concept to concept, from idea to idea! I have said many times that Marx's boundary is reality, yet even on this question the Ah Qs have asked N times and declared N times that I cannot answer. Ah Q is Ah Q. Here are some truly excellent specimens -- three quotes with commentary as follows (since this is about the matter and not the person, specific names are removed):"}),"\n",(0,i.jsxs)(t.p,{children:["\"[Tangfen] has been retreating from 'dimensions' to 'value categories' to 'categories' to 'dialectics' to 'realistic logic'\" ",(0,i.jsx)("br",{}),"\n===================== ",(0,i.jsx)("br",{}),'\nI have never said anything about dialectics -- don\'t smuggle in your own private goods. Also, I\'ve been introducing Marx according to my own train of thought, and in Ah Q\'s eyes this continuous introduction becomes "a full retreat"? Excuse me, do you people know Chinese? Do you know what "retreat" means? The biggest characteristic of all anti-Marx people is that they flee from reality and start only from a priori imagination. They think that because the word "retreat" floated up in their brains, the other person has actually retreated! Must I forever only talk about things related to "dimensions" to not be retreating? Must everyone on this forum forever only talk about one single thing, otherwise they\'re all retreating?']}),"\n",(0,i.jsxs)(t.p,{children:["\"Talking about formal logic is not 'distorting' Marxism, because formal logic exists everywhere in our lives at all times. ",(0,i.jsx)("br",{}),'\nThe reason I study formal logic is not to oppose dialectics, let alone to oppose Marx." ',(0,i.jsx)("br",{}),"\n============== ",(0,i.jsx)("br",{}),"\nAnti-Marx people love nothing more than muddling the topic. Who's stopping you from studying formal logic now? Whether you study Ah Q is your freedom -- study or don't! But what I'm pointing out now is that the premise of Marx's theory is not formal logic, dialectical logic, or any other a priori logic, but rather the realistic logical relationships. That's the key point! Trying to muddle the topic? No way!"]}),"\n",(0,i.jsxs)(t.p,{children:["\"You can't call everything 'the totality of reality and relationships,' right? -- For example, labor, economy, commodities, value -- wouldn't that become a complete mess?\" ",(0,i.jsx)("br",{}),"\n============ ",(0,i.jsx)("br",{}),"\nPlaying the distortion trick again. The labor category is the totality of all real labor relationships; the economic category is the totality of all real economic relationships. How would that result in calling everything \"the totality of reality and relationships\"? Of course, in Ah Q's mind, the world belongs to Ah Q. He thinks that because Ah Q's brain is a mess, the world must be a mess too!"]}),"\n",(0,i.jsx)(t.p,{children:"Alright, wasting time on Ah Q is unnecessary, but this struggle between Marx and anti-Marx is omnipresent. This must continue!"})]})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(96540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);